function finish(questions: QuizQuestion[]): QuizQuestion[] {
  let choiceSlot = 0;
  let comparisonSlot = 0;
  return questions.map((source) => {
    const q = formatQuizCodeQuestion(source);
    if (q.type === 'single_choice' || q.type === 'predict_output') {
      const options = [...q.options];
      const correct = options.splice(q.answer, 1)[0];
      const answer = choiceSlot++ % 4;
      options.splice(answer, 0, correct);
      return { ...q, options, answer };
    }
    if (q.type === 'code_comparison') {
      const answer = (comparisonSlot++ % 2) as 0 | 1;
      if (q.answer === answer) return q;
      return { ...q, a: q.b, b: q.a, answer };
    }
    return q;
  });
}

export const WORLD_11_QUIZ: QuizQuestion[] = finish([...lessonQuestions, ...setQuestions]);
export const WORLD_11_BOSS_QUIZ: QuizQuestion[] = finish(bossQuestions);
